<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/read_queries.php';
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]); $action = (string)($_GET['accion'] ?? '');
if ($id === false || !in_array($action, ['prioridad','cancelar'], true)) { http_response_code(404); exit('Acción no disponible.'); }
require_permission($action === 'prioridad' ? 'SOLICITUDES_AJUSTAR_PRIORIDAD' : 'SOLICITUDES_CANCELAR');
try { $sets=read_procedure_sets('EXEC dbo.sp_obtener_solicitud @solicitud_id=?;', [(int)$id]); $solicitud=$sets[0][0]??null; } catch(PDOException){ read_error_response(); }
if (!is_array($solicitud) || !in_array($solicitud['estado'], ['REGISTRADA','PENDIENTE_ASIGNACION'], true)) { http_response_code(409); exit(ui_notice('La solicitud ya no admite esta acción.', 'warning')); }
?>
<div class="modal is-active" role="dialog" aria-modal="true" aria-labelledby="titulo-accion"><div class="modal-background" data-close-modal></div><div class="modal-card"><header class="modal-card-head"><p class="modal-card-title" id="titulo-accion"><?= $action==='prioridad'?'Ajustar prioridad':'Cancelar solicitud' ?></p><button class="modal-close icon-button" type="button" aria-label="Cerrar" data-close-modal><?= svg_icon('close') ?></button></header><form hx-post="/solicitudes/accion.php" hx-target="#mensaje-accion" hx-swap="innerHTML"><section class="modal-card-body"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="solicitud_id" value="<?= (int)$id ?>"><input type="hidden" name="accion" value="<?= e($action) ?>"><div id="mensaje-accion" role="alert"></div><p>Solicitud <strong><?= e($solicitud['codigo_solicitud']) ?></strong> · <?= status_tag($solicitud['estado']) ?></p><?php if($action==='prioridad'):?><div class="field"><label class="label" for="prioridad">Prioridad</label><div class="select is-fullwidth"><select id="prioridad" name="prioridad" required><option>NORMAL</option><option>ALTA</option><option>URGENTE</option></select></div></div><div class="field"><label class="label" for="justificacion">Justificación</label><textarea class="textarea" id="justificacion" name="justificacion" maxlength="500" required></textarea></div><?php else:?><div class="field"><label class="label" for="motivo">Motivo de cancelación</label><textarea class="textarea" id="motivo" name="motivo" maxlength="500" required></textarea></div><p class="help">Esta acción no se puede revertir desde la aplicación.</p><?php endif;?></section><footer class="modal-card-foot"><div class="buttons"><button class="button <?= $action==='cancelar'?'is-danger':'is-primary' ?>" type="submit"><?= $action==='cancelar'?'Confirmar cancelación':'Guardar' ?></button><button class="button button-secondary" type="button" data-close-modal>Cancelar</button></div></footer></form></div></div>
